options.function:
const series = data.series || [];
const stations = [];

if (series.length > 0 && series[0].fields) {
  const fields = series[0].fields;
  const nameField = fields.find(f => f.name === 'estacion' || f.name === 'Estacion');
  const count = nameField ? nameField.values.length : 0;
  for (let i = 0; i < count; i++) {
    stations.push(nameField ? nameField.values[i] : 'Estación ' + (i+1));
  }
}

const colors = ['#10b981', '#06b6d4', '#f59e0b', '#ec4899', '#8b5cf6', '#3b82f6'];
const radarSeriesData = [];

if (series.length > 0 && series[0].fields) {
  const fields = series[0].fields;
  const nameField = fields.find(f => f.name === 'estacion' || f.name === 'Estacion');
  const wqiField = fields.find(f => f.name === 'wqi_score');
  const ecField = fields.find(f => f.name === 'ec_us_cm');
  const turbField = fields.find(f => f.name === 'turbidez_ntu');
  const phField = fields.find(f => f.name === 'ph');
  const flowField = fields.find(f => f.name === 'caudal_m3s');

  const count = nameField ? nameField.values.length : 0;
  for (let i = 0; i < count; i++) {
    radarSeriesData.push({
      value: [
        wqiField ? Number(wqiField.values[i]) : 20,
        ecField ? Number(ecField.values[i] / 20) : 30,
        turbField ? Number(turbField.values[i]) : 10,
        phField ? Number(phField.values[i] * 10) : 75,
        flowField ? Number(flowField.values[i] * 10) : 25
      ],
      name: nameField ? String(nameField.values[i]) : 'Estación ' + (i+1),
      itemStyle: { color: colors[i % colors.length] },
      areaStyle: { opacity: 0.25 }
    });
  }
}

return {
  backgroundColor: 'transparent',
  tooltip: { trigger: 'item' },
  legend: {
    bottom: 5,
    textStyle: { color: '#94a3b8', fontSize: 11 },
    data: stations
  },
  radar: {
    indicator: [
      { name: 'WQI (0-100)', max: 100 },
      { name: 'Salinidad (EC/20)', max: 100 },
      { name: 'Turbidez (NTU)', max: 80 },
      { name: 'pH (x10)', max: 100 },
      { name: 'Caudal (m³/s x10)', max: 100 }
    ],
    shape: 'polygon',
    splitNumber: 4,
    axisName: { color: '#38bdf8', fontSize: 11, fontWeight: 'bold' },
    splitLine: { lineStyle: { color: 'rgba(56, 189, 248, 0.2)' } },
    splitArea: { show: false },
    axisLine: { lineStyle: { color: 'rgba(56, 189, 248, 0.3)' } }
  },
  series: [{
    type: 'radar',
    data: radarSeriesData
  }]
};
